using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Threading.Tasks;
internal sealed partial class ControlWindow {
 readonly Button handoff=new SoftButton();readonly Queue<Dictionary<string,object>> diagnosticEvents=new Queue<Dictionary<string,object>>();FaultRecord lastFault;FaultHandoffForm faultWindow;string lastFaultKey;Action faultRetry;
 void InstallFaultEntry(){handoff.Text="提交给Agent";handoff.Name="AgentHandoff";handoff.Dock=DockStyle.Fill;handoff.Margin=new Padding(U(8),0,0,0);var grid=(TableLayoutPanel)banner.Controls[0];grid.Controls.Remove(countdown);grid.Controls.Remove(activeName);grid.SetColumnSpan(lease,1);grid.Controls.Add(countdown,1,2);grid.Controls.Add(handoff,1,0);grid.SetRowSpan(handoff,2);handoff.Click+=(s,e)=>OpenFaultHandoff(false);
  try{string p=Path.Combine(Common.Root,"diagnostics","last-fault.json");if(File.Exists(p)&&new FileInfo(p).Length<=98304){LocalImport.NoLinks(p);lastFault=FaultSafety.Sanitize(Common.Json.Deserialize<FaultRecord>(Common.ReadShared(p)));handoff.Text="提交给Agent";}}catch{}
 }
 FaultRecord CaptureFault(string category,string operation,string stage,string reason,ImportCandidate candidate=null,bool demo=false){
  var f=new FaultRecord{SchemaVersion=1,Id="diag-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,12),EventTime=DateTimeOffset.Now.ToString("o"),Category=FaultSafety.Category(category),Operation=operation,Stage=stage,Reason=reason,UserSymptom="用户尚未补充",Demo=demo,SessionRelative=FaultSafety.RelativeLog(Session),RunRelative=FaultSafety.RelativeLog(CurrentRun),WorkerState=WorkerRole,PlayerState=PlayerRole,CardCount=library.Doc.Items.Count,
   DataState=library.Error==null?"壁纸列表仍可读取（"+library.Doc.Items.Count+"张）；本次失败前后的磁盘一致性尚未完整核对。":"登记数据读取异常，原文件保留状态需核对。",
   CleanupState=Clean?"当前自有播放任务已确认退出或未启动；失败操作的临时文件见诊断证据。":"播放或临时任务的清理尚未全部确认。",
   DesktopState=CurrentRun==null?"本次会话尚未请求播放；外部桌面状态尚未核查。":"当前或先前存在播放会话；桌面恢复状态需结合该任务证据核对。",Events=diagnosticEvents.ToList()};
  if(candidate!=null){f.ResourceId=candidate.Id;f.ResourceSha256=candidate.Check==null?candidate.DiscoveredSha256:candidate.Check.Sha256;f.SourcePath=candidate.Source;f.NameSource=candidate.NameSource;var item=library.Doc.Items.FirstOrDefault(x=>x.RegisteredSha256==f.ResourceSha256);if(item!=null)f.CatalogId=item.Id;}
  else {WallpaperItem item=null;if(category!="start"&&activeRunRequest!=null){string id=Common.S(activeRunRequest,"selectedCatalogId");item=library.Doc.Items.FirstOrDefault(x=>x.Id==id);}if(item==null)item=selected;if(item!=null){f.CatalogId=item.Id;f.ResourceId=OfficialNameStore.ItemId(item);f.ResourceSha256=item.RegisteredSha256;f.SourcePath=item.SourcePath;f.PreviewConfirmedSha256=item.PreviewConfirmedSha256;f.DesktopConfirmedSha256=item.DesktopConfirmedSha256;f.NameSource=item.NameSource;}}
  if(category=="name-cover"&&operation=="后台读取名称"){f.CatalogId=null;f.ResourceId=null;f.ResourceSha256=null;f.SourcePath=null;f.NameSource=null;f.PreviewConfirmedSha256=null;f.DesktopConfirmedSha256=null;}return FaultSafety.Sanitize(f);
 }
 void RecordFault(string category,string operation,string stage,string reason,ImportCandidate candidate=null,Action retryAction=null,bool nonBlocking=false){
  if(PlaybackFailure.KeepPrimary(lastFault,nonBlocking,State)){Write("diagnostic-supplement",new{retainedIncidentId=lastFault.Id,operation=operation,stage=stage,reason=FaultSafety.Text(reason,400),primaryFaultPreserved=true});return;}
  try{string key=category+"|"+operation+"|"+stage+"|"+FaultSafety.Text(reason,200)+"|"+(candidate==null?(CurrentRun??(selected==null?"":selected.Id)):candidate.Source);if(key==lastFaultKey)return;lastFaultKey=key;lastFault=CaptureFault(category,operation,stage,reason,candidate);faultRetry=retryAction;lastFault.RetryAllowed=retryAction!=null;
   handoff.Text="提交给Agent";handoff.AccessibleDescription=FaultSafety.Summary(lastFault);if(!nonBlocking){handoff.ForeColor=Color.FromArgb(156,68,30);libraryHint.Text=operation+"未完成。"+(Clean?"自有播放任务已退出或未启动。":"清理尚未全部确认。")+"可复制信息交给Agent。";}
   string root=DiagnosticBundle.Root;Directory.CreateDirectory(root);LocalImport.NoLinks(root);Common.ReplaceJson(Path.Combine(root,"last-fault.json"),lastFault);if(nonBlocking)Write("nonblocking-diagnostic-recorded",new{incidentId=lastFault.Id,operation=operation,stage=stage,reason=FaultSafety.Text(reason,240),listAndImportUnaffected=true,savedNamesPreserved=true});
  }catch{ /* Reporting never replaces the original failure or cleanup. */ }
 }
 void ObserveDiagnosticEvent(string phase,object data){
  if(phase.StartsWith("diagnostic-",StringComparison.Ordinal))return;
  // A bounded projection, never raw logs, headers, credentials or resource text.
  string[] allowed={"playback-preparation-started","playback-preparation-cancel-requested","playback-preparation-cancelled","playback-preparation-failed","ui-state","controller-ready","controller-error","source-read-failed","role-observation","operation-begin","operation-complete","operation-incomplete","close-cleanup-unconfirmed","local-import-failed","local-import-task-start","local-import-task-exit","candidate-check-result","catalog-error","cover-error","wallpaper-remove-failed","preview-cover-failed","official-name-refresh-failed","official-name-refresh","official-name-refresh-cancelled","discovery-check-failed","preview-confirmation-error","recovery-operation-error","handoff-rejected","controller-close-request","controller-closed","local-import-close-clean","official-name-close-clean"};
  if(allowed.Contains(phase)){diagnosticEvents.Enqueue(FaultSafety.Event(phase,data));while(diagnosticEvents.Count>60)diagnosticEvents.Dequeue();}
  Dictionary<string,object> d;try{d=Common.Json.Deserialize<Dictionary<string,object>>(Common.Json.Serialize(data));}catch{return;}
  if(phase=="ui-state"){string state=Common.S(d,"state");if(!(state=="failed-cleaned"&&lastFault!=null)&&(state.Contains("failed")||state.Contains("unconfirmed")||state=="stop-timeout"||state=="worker-lost"||state=="worker-stalled"))RecordFault(state.Contains("stop")||state.Contains("cleanup")||state.Contains("close")||state.Contains("worker-")?"stop":"start",state.Contains("stop")||state.Contains("cleanup")||state.Contains("close")||state.Contains("worker-")?"停止或退出壁纸":"启动壁纸",state,Common.S(d,"message"));}
  string reason=Common.S(d,"error");if(reason.Length==0)reason=Common.S(d,"reason");
  switch(phase){case "catalog-error":RecordFault("save","登记本地壁纸",phase,reason);break;case "cover-error":case "preview-cover-failed":RecordFault("name-cover","保存封面",phase,reason);break;case "official-name-refresh-failed":RecordFault("name-cover","读取或保存名称",phase,reason);break;case "wallpaper-remove-failed":RecordFault("save","从列表移除壁纸",phase,reason);break;case "preview-confirmation-error":RecordFault("save","保存画面确认",phase,reason);break;case "handoff-rejected":RecordFault("environment","核对自有播放器身份",phase,reason);break;case "recovery-operation-error":case "close-cleanup-unconfirmed":RecordFault("stop","停止或退出壁纸",phase,reason);break;case "discovery-check-failed":RecordFault("check","检查本地候选",phase,reason);break;}
 }
 void OpenFaultHandoff(bool autoCopy=false){if(closing)return;if(faultWindow!=null&&!faultWindow.IsDisposed){faultWindow.Activate();return;}var f=lastFault??CaptureFault("environment","当前状态交接","用户主动打开交接入口","当前没有记录到具体故障；请补充看到的现象");f=Common.Json.Deserialize<FaultRecord>(Common.Json.Serialize(f));if(lastFault==null)f.StatusOnly=true;if(importDialog==null)f.RetryAllowed=false;faultWindow=new FaultHandoffForm(f,Write,faultRetry);faultWindow.FormClosed+=(s,e)=>faultWindow=null;faultWindow.Show(this);}
 async Task StopFaultHandoff(){if(faultWindow!=null&&!faultWindow.IsDisposed)await faultWindow.StopForOwner();}
}
